export const askController = async (
  req: Request,
  res: Response,
): Promise<void> => {
  try {
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');

    const { url: repoUrl, prompt: question, type, sessionId } = req.body;

    const userId = (req as any).user?.userId;

    res.write(
      `data: ${JSON.stringify({
        type: 'status',
        message: 'Retrieving code...',
      })}\n\n`,
    );

    const { answerQuestion } = await import('./rag.service.js');
    const response = await answerQuestion(repoUrl, question, type, sessionId);

    const answer = String(response.result.response.answer);
    const citations = response.result.response.citations;

    const chunkSize = 5;
    const words = answer.split(' ');

    for (let i = 0; i < words.length; i += chunkSize) {
      const chunk = words.slice(i, i + chunkSize).join(' ');
      res.write(
        `data: ${JSON.stringify({ type: 'answer_chunk', content: chunk })}\n\n`,
      );
      await new Promise((resolve) => setTimeout(resolve, 100));
    }

    res.write(
      `data: ${JSON.stringify({
        type: 'citations',
        data: citations,
        question: question,
      })}\n\n`,
    );
    res.write(`data: ${JSON.stringify({ type: 'complete' })}\n\n`);
    await Conversation.updateOne(
      {
        sessionId,
        repoUrl,
        userId,
      },
      {
        $push: {
          messages: [
            { role: 'user', content: question, timestamp: new Date() },
            {
              role: 'assistant',
              content: answer,
              citations,
              timestamp: new Date(),
            },
          ],
        },
        $setOnInsert: {
          repoUrl,
          userId,
          sessionId,
        },
      },
      { upsert: true },
    );

    appendQueryLog({
      userId,
      sessionId,
      repoUrl,
      query: question,
    });

    res.end();
  } catch (err: any) {
    console.log('--- Error inside askController ------------');
    console.error(err);

    res.write(
      `data: ${JSON.stringify({ type: 'error', message: err.message })}\n\n`,
    );
    res.end();
  }
};

