export type Citations = {
  file: string;
  startLine: number;
  endLine: number;
  snippet: string;
};

export type Message = {
  role: 'user' | 'assistant';
  content: string; // Always the main text
  citations?: Citations[]; // Only for assistant
  timestamp: Date;
};

export interface IConversation {
  sessionId: string;
  userId?: string;
  repoUrl: string;
  messages: Message[];
}

const conversationSchema = new Schema<IConversation>(
  {
    sessionId: { type: String, required: true },
    userId: { type: String, required: true },
    repoUrl: { type: String, required: true },
    messages: [
      {
        role: { type: String, enum: ['user', 'assistant'], required: true },
        content: { type: String, required: true },
        citations: {
          type: [
            {
              file: { type: String },
              startLine: { type: Number },
              endLine: { type: Number },
              snippet: { type: String },
            },
          ],
          default: undefined,
        },
        timestamp: { type: Date, default: Date.now },
      },
    ],
  },
  {
    timestamps: true, // automatically adds createdAt and updatedAt
  }
);

const Conversation = mongoose.model<IConversation>(
  'Conversation',
  conversationSchema
);
export default Conversation;

// Receives queries from the client and invokes RAG processing logic.
// answerQuestion is lazy-loaded so app can listen and respond to /api/keep-alive
// before LangChain/Qdrant load (avoids long cold start and 503 after restarts).
import { Request, Response } from 'express';
import Conversation from '../../models/conversation.model.js';
import Query from '../../models/query.model.js';
import User from '../../models/user.model.js';
import { appendQueryLog } from '../../utils/usageReport.js';

export const askController = async (
  req: Request,
  res: Response,
): Promise<void> => {
  try {
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');

    const { url: repoUrl, prompt: question, type, sessionId } = req.body;

    const userId = (req as any).user?.userId;

    res.write(
      `data: ${JSON.stringify({
        type: 'status',
        message: 'Retrieving code...',
      })}\n\n`,
    );

    const { answerQuestion } = await import('./rag.service.js');
    const response = await answerQuestion(repoUrl, question, type, sessionId);

    const answer = String(response.result.response.answer);
    const citations = response.result.response.citations;

    const chunkSize = 5;
    const words = answer.split(' ');

    for (let i = 0; i < words.length; i += chunkSize) {
      const chunk = words.slice(i, i + chunkSize).join(' ');
      res.write(
        `data: ${JSON.stringify({ type: 'answer_chunk', content: chunk })}\n\n`,
      );
      await new Promise((resolve) => setTimeout(resolve, 100));
    }

    res.write(
      `data: ${JSON.stringify({
        type: 'citations',
        data: citations,
        question: question,
      })}\n\n`,
    );
    res.write(`data: ${JSON.stringify({ type: 'complete' })}\n\n`);
    await Conversation.updateOne(
      {
        sessionId,
        repoUrl,
        userId,
      },
      {
        $push: {
          messages: [
            { role: 'user', content: question, timestamp: new Date() },
            {
              role: 'assistant',
              content: answer,
              citations,
              timestamp: new Date(),
            },
          ],
        },
        $setOnInsert: {
          repoUrl,
          userId,
          sessionId,
        },
      },
      { upsert: true },
    );

    appendQueryLog({
      userId,
      sessionId,
      repoUrl,
      query: question,
    });

    res.end();
  } catch (err: any) {
    console.log('--- Error inside askController ------------');
    console.error(err);

    res.write(
      `data: ${JSON.stringify({ type: 'error', message: err.message })}\n\n`,
    );
    res.end();
  }
};

